def solve():
    a = {1: 1, 2: 1}

    # We calculate up to N=30 to check patterns
    N_max = 30

    for n in range(3, N_max + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        # We assume a_{n-1} and n - a_{n-1} are already in 'a' since n >= 3.
        # a_{n-1} is known. Let x = a_{n-1}
        x = a[n-1]

        # We need a_x and a_{n-x}. Since a_n is non-decreasing, and x <= n-1, a_x is known.
        # Also n-x = n - a_{n-1}. Since a_{n-1} >= 1, n-x <= n-1. So a_{n-x} is known.

        a[n] = a[x] + a[n - x]

    print("n:", list(range(1, N_max + 1)))
    print("a_n:", [a[i] for i in range(1, N_max + 1)])

solve()

def solve_sequence(N):
    # a_n sequence, indexed from 1. We use a dictionary for memoization.
    a = {1: 1, 2: 1}

    def compute_a(n):
        if n in a:
            return a[n]
        if n < 1:
            raise ValueError("Index must be positive")

        # Check recursion limit safety before proceeding
        if n > 2000: # Safety break for calculation feasibility
             raise RecursionError("N too large for reliable calculation.")

        # Recursive step: a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

        # We must compute a_{n-1} first
        a_n_minus_1 = compute_a(n - 1)

        # Now compute the two terms needed for a_n

        # Term 1: a_{a_{n-1}}
        index1 = a_n_minus_1
        term1 = compute_a(index1)

        # Term 2: a_{n - a_{n-1}}
        index2 = n - a_n_minus_1
        term2 = compute_a(index2)

        result = term1 + term2
        a[n] = result
        return result

    print("Sequence calculated up to N:")
    for i in range(1, N + 1):
        try:
            val = compute_a(i)
            # Print only key checkpoints for brevity in checking trend
            if i % 10 == 0 or i <= 12 or i == N:
                print(f"a_{i} = {val}")
        except RecursionError as e:
            print(f"Calculation failed for n={i}: {e}")
            break

# Test up to N=100
N_test = 100
print(f"--- Computing sequence up to N={N_test} ---")
solve_sequence(N_test)
